function setup(t,count=300,extra=[],sourceOptions={},SourceStore=RoomStore,sourceWriter=withCurrentRoomWriter,sourceExport=exportNdjsonText){const directory=mkdtempSync(join(tmpdir(),'durable-coverage-'));t.after(()=>rmSync(directory,{recursive:true,force:true}));const source=new SourceStore(':memory:',sourceOptions);t.after(()=>source.close());const events=[...initialRoom(),...extra];for(let n=0;n<count;n++)events.push(event({id:'durable-event-'+n,roomId:'commons',actorId:'owner',type:'message.posted',data:{messageId:'durable-message-'+n,body:n===0?'u'.repeat(8191)+'😀'+'\n\t"'.repeat(3000):'Useful exact source evidence '+n}}));source.initialize(events,{representation:'normalized-current-v1'});const key=source.issueAccessKey('commons','owner'),bytes=Buffer.alloc(512*1024);for(let n=0;n<bytes.length;n++)bytes[n]=n%256;source.transaction(()=>sourceWriter(source.db,'commons',()=>source.db.prepare("INSERT INTO room_attachments(room_id,id,uploader_id,filename,media_type,byte_length,sha256,bytes,state,created_at,expires_at,message_id) VALUES('commons','durable-blob','owner','synthetic.bin','application/octet-stream',?,?,?,'staged',?,?,NULL)").run(bytes.length,createHash('sha256').update(bytes).digest('hex'),bytes,Date.now(),Date.now()+3600000)));return{source,key,bytes,text:sourceExport(source.db),filename:join(directory,'target.sqlite')};}
// Complete only absent v45 fences after the explicit empty-target fixture transition.
// Never register a v46 function on the genuine old connection or replace a guard.
function completeEmptyV45Fixture(held) {
 assert.equal(held.db.prepare('PRAGMA user_version').get().user_version,45);
 assert.equal(held.db.prepare('SELECT count(*) n FROM rooms').get().n,0);
 assert.equal(held.db.prepare('SELECT count(*) n FROM operator_actions').get().n,0);
 for(const def of fenceDefinitions(45)) {
  const table=def.name.slice('writer_v45_'.length).replace(/_(insert|update|delete)$/,'');
  if(!held.db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?").get(table))continue;
  const actual=held.db.prepare('SELECT sql FROM sqlite_master WHERE name=?').get(def.name);
  if(actual)assert.equal(actual.sql,def.sql);else held.db.exec(def.sql);
 }
}
async function post(store,body,{json=false,credential=token}={}){const response=await operatorRestoreResponse(new Request(url,{method:'POST',headers:{Authorization:'Bearer '+credential,...(json?{'Content-Type':'application/json'}:{})},body:json?JSON.stringify(body):body}),token,store);const result={status:response.status,body:await response.clone().json()};Object.defineProperty(result,'raw',{value:response});return result;}
const request=(body,id)=>({restoreId:body.restoreId,sourceSeal:body.sourceSeal,expectedRevision:body.revision,requestId:id});
test('operator coverage persists bounded progress across cold stores and only admits after full audit',async t=>{
 const f=setup(t),held=new RoomStore(f.filename);t.after(()=>held.close());const prepared=held.db.prepare("UPDATE credentials SET revoked=1 WHERE kind='access'");let response=await post(held,f.text);assert.equal(response.status,202);assert.equal(response.body.verified,false);assert.equal(response.body.phase,'coverage');assert.equal(restoreProgress(held.db).seal.reportVersion,1);assert.throws(()=>held.headSequence('commons'),error=>error.status===503);assert.throws(()=>prepared.run(),/restore target is sealed/);const repeated=await post(held,f.text);assert.deepEqual(repeated,response);const different=await post(held,f.text+'\n');assert.equal(different.status,422);assert.equal(restoreProgress(held.db).revision,response.body.revision);
 let steps=0,previous=0,lastRequest,lastResponse,active=held;const reportGuard=reportProgressGuard(()=>active,assert);
 while(response.body.pending){const store=new RoomStore(f.filename);active=store;try{const input=request(response.body,'step_'+steps),before=restoreProgress(store.db),mark=reportGuard.before(before);lastRequest=input;response=await post(store,input,{json:true});assert.ok([200,202].includes(response.status),JSON.stringify(response.body));const duplicate=await post(store,input,{json:true});assert.deepEqual(duplicate,response,'latest receipt must replay byte-equivalent result');if(response.status===202){assert.equal(response.body.verified,false);assert.ok(response.body.progress.rows-previous<=128);assert.ok(response.body.progress.rows>=previous);previous=response.body.progress.rows;const stale=await post(store,{...input,requestId:'different_'+steps},{json:true});assert.equal(stale.status,409);assert.throws(()=>store.headSequence('commons'),error=>error.status===503);assert.ok(restoreProgress(store.db).revision>before.revision);}reportGuard.after(mark,restoreProgress(store.db));lastResponse=response;steps++;assert.ok(reportGuard.summary().preReportCalls<250,'original pre-report completion bound');}finally{store.close();}}
 await completeOperatorRestore(response.raw,token,held);
 assert.equal(response.status,200);assert.equal(response.body.verified,true);assert.equal(response.body.engineChecks.stage,'complete');assert.ok(response.body.engineChecks.quickTables>200);assert.ok(response.body.engineChecks.foreignKeyTables>=response.body.engineChecks.quickTables);assert.equal(response.body.reportVersion,1);assert.equal(response.body.recovery.contractVersion,1);assert.equal(response.body.audit.ok,true);const cold=new RoomStore(f.filename);try{auditRecovery(cold);assert.equal(cold.restoreStatus().pending,false);assert.equal(cold.headSequence('commons'),f.source.headSequence('commons'));assert.deepEqual(Buffer.from(cold.db.prepare("SELECT bytes FROM room_attachments WHERE id='durable-blob'").get().bytes),f.bytes);assert.equal(cold.db.prepare("SELECT message_id FROM room_attachments WHERE id='durable-blob'").get().message_id,null);assert.deepEqual(await post(cold,lastRequest,{json:true}),lastResponse,'final receipt must survive cold reopen');}finally{cold.close();}t.diagnostic(JSON.stringify({sourceMessages:300,steps,reportProgress:reportGuard.summary(),maxCoverageRows:128,blobBytes:f.bytes.length,coldReceiptReplay:true}));
});
test('failed checkpoint rolls back cursor and receipt while keeping target freeze and ordinary refusal',async t=>{
 const f=setup(t,150),store=new RoomStore(f.filename);t.after(()=>store.close());const sealed=await post(store,f.text);assert.equal(sealed.status,202);const before=restoreProgress(store.db),prepare=store.db.prepare.bind(store.db);let injected=false;store.db.prepare=sql=>{const statement=prepare(sql);if(!/^UPDATE current_restore_admission SET phase=/.test(sql))return statement;return new Proxy(statement,{get(target,key){const fn=Reflect.get(target,key,target);if(key!=='run')return typeof fn==='function'?fn.bind(target):fn;return(...args)=>{fn.apply(target,args);injected=true;throw Error('synthetic after-checkpoint fault');};}});};const input=request(sealed.body,'fault_step');const failed=await post(store,input,{json:true});assert.equal(failed.status,422);assert.equal(injected,true);store.db.prepare=prepare;assert.deepEqual(restoreProgress(store.db),before);assert.throws(()=>store.db.prepare("UPDATE credentials SET revoked=1").run(),/restore target is sealed/);assert.throws(()=>store.headSequence('commons'),error=>error.status===503);const retried=await post(store,input,{json:true});assert.equal(retried.status,202);assert.ok(retried.body.progress.rows>0);
});

test('real process interruption before and after checkpoint commit preserves exact durable progress',async t=>{
 const f=setup(t,150),store=new RoomStore(f.filename);t.after(()=>store.close());const sealed=await post(store,f.text);assert.equal(sealed.status,202);const inputFile=f.filename+'.request.json',input=request(sealed.body,'process_step');writeFileSync(inputFile,JSON.stringify(input));const before=restoreProgress(store.db);const child=mode=>{const run=spawnSync(process.execPath,['tests/fixtures/durable-coverage-operator-child.mjs',f.filename,inputFile,mode],{encoding:'utf8',timeout:30000,maxBuffer:1024*1024});assert.equal(run.status,77,run.stdout+'\n'+run.stderr);return JSON.parse(run.stdout.trim().split('\n').at(-1));};assert.equal(child('before-commit').phase,'after-update-before-commit');assert.deepEqual(restoreProgress(store.db),before);const committed=child('committed');assert.equal(committed.status,202);assert.equal(restoreProgress(store.db).revision,before.revision+1);assert.ok(committed.result.progress.rows>0);assert.deepEqual(child('committed'),committed,'lost committed response must replay same receipt in another process');assert.throws(()=>store.db.prepare("UPDATE credentials SET revoked=1").run(),/restore target is sealed/);
});
test('genuine old4aa warm prepared writer, cold constructor and old exact-guard suspension refuse new sealed bookkeeping',async t=>{
 const f=setup(t,10),oldRoot=f.filename+'.old4aa';mkdirSync(oldRoot);const archived=execFileSync('git',['archive','--format=tar','4aa07fa84','server','src','client','strings','cloudflare/room-backup.mjs','package.json'],{maxBuffer:64*1024*1024});execFileSync('tar',['-xf','-','-C',oldRoot],{input:archived});symlinkSync(realpathSync('node_modules'),join(oldRoot,'node_modules'));const {RoomStore:OldStore}=await import(pathToFileURL(join(oldRoot,'server/store.mjs'))),oldAdmission=await import(pathToFileURL(join(oldRoot,'server/restore-admission.mjs'))),oldCurrent=await import(pathToFileURL(join(oldRoot,'server/current-room-repository.mjs')));const held=new OldStore(f.filename);t.after(()=>held.close());const prepared=held.db.prepare("UPDATE credentials SET revoked=1 WHERE kind='access'");assert.equal(held.db.prepare('SELECT count(*) n FROM rooms').get().n,0);assert.equal(held.db.prepare('SELECT count(*) n FROM operator_actions').get().n,0);
 // Explicit offline transition of a verified-empty experimental45 target; not
 // an automatic migration or a waiver for a populated historical database.
 // Old4aa current schema is verified before explicitly replacing its format
 // permit guard; new constructor adds only previously absent native guards.
 // Keeping the old permit definition correctly refuses the native-work-2 source.
 held.transaction(()=>{oldAdmission.verifyRestoreControl(held.db);oldCurrent.verifyCurrentRoomSchema(held.db);const permitDefinition=CURRENT_ROOM_GUARDS.match(/CREATE TRIGGER IF NOT EXISTS current_room_permit_update[\s\S]*?(?=\nCREATE TRIGGER IF NOT EXISTS current_room_permit_insert)/)?.[0];assert.ok(permitDefinition);held.db.exec('DROP TRIGGER current_room_permit_update');held.db.exec(permitDefinition);for(const[name]of oldAdmission.RESTORE_CONTROL_GUARDS)held.db.exec('DROP TRIGGER '+name);held.db.exec('DROP TABLE current_restore_admission');held.db.exec(RESTORE_CONTROL_SCHEMA);for(const[,sql]of RESTORE_CONTROL_GUARDS)held.db.exec(sql);for(const def of writerFenceDefinitions.filter(def=>def.name.startsWith('writer_v45_current_restore_admission_')||def.name.startsWith('writer_v45_current_restore_audit_scratch_')))held.db.exec(def.sql);});
 completeEmptyV45Fixture(held);
 const current=new RoomStore(f.filename);t.after(()=>current.close());const sealed=await post(current,f.text);assert.equal(sealed.status,202);const before=restoreProgress(current.db);assert.throws(()=>prepared.run(),/^Error: no such function: project_room_writer_v46$/);assert.throws(()=>new OldStore(f.filename),/^Error: Database schema is newer than this service$/);assert.throws(()=>oldAdmission.verifyRestoreControl(current.db),/requires (?:operator )?reconciliation/);const exec=held.db.exec.bind(held.db);let drops=0;held.db.exec=sql=>{if(/^DROP TRIGGER current_restore_admission_/.test(sql))drops++;return exec(sql);};assert.throws(()=>oldAdmission.withRestoreTransaction(held,()=>oldAdmission.withExactRestoreGuards(held.db,oldAdmission.RESTORE_CONTROL_GUARDS,()=>held.db.prepare("UPDATE current_restore_admission SET state='clear',restore_id=NULL").run())),/requires (?:operator )?reconciliation/);assert.equal(drops,0,'old exact-guard suspension must refuse BEFORE DROP');assert.deepEqual(restoreProgress(current.db),before);assert.equal(current.db.prepare("SELECT revoked FROM credentials WHERE kind='access'").get().revoked,0);const step=await post(current,request(sealed.body,'new_operator_step'),{json:true});assert.equal(step.status,202);t.diagnostic(JSON.stringify({oldPin:'4aa07fa84',oldWarmPreparedDenied:true,oldColdDenied:true,oldExactDropAttempts:drops,newContinuation:step.status}));
});

