 t.diagnostic('DURABLE_COVERAGE_COMPARISON '+JSON.stringify({sourcePin:'2075f27e897c9843048012559f457bf11607d884',oldRuntimePin:'4aa07fa84',candidatePin:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),sameOriginalSourceSha256:createHash('sha256').update(f.text).digest('hex'),originalBytes:Buffer.byteLength(f.text),oldPartial,oldProcesses:[oldFirst,oldSecond],newPartial:partial,newSourceLoadAndSeal:sealed,newProcesses:newSteps,continuationProgress,finalUnboundedAudit:finalAudit,oldDurableCoverageAdvance:0,newDurableCoverageAdvance:256,finalVerified:true,exactApplicationTableDigestsExceptTargetRestoreControlAndValidatedSchemaStamp:true,wholeRecoveryBounded:false,metrics:'returned rows and UTF8/BLOB cell bytes after constructor, not physical SQLite reads or CPU; source load and final audit remain monolithic'}));
