test('independent membership phase detects an unproven payload after a once-valid source coverage seal',async t=>{
 const f=setup(t,150);let store=new RoomStore(f.filename);t.after(()=>store.close());let response=await post(store,f.text),n=0;while(response.body.phase==='coverage'){response=await post(store,request(response.body,'orphan_cover_'+n++),{json:true});assert.equal(response.status,202);}const guards=store.db.prepare("SELECT name,sql FROM sqlite_master WHERE name IN ('restore_frozen_current_room_records_insert','current_room_guard_current_room_records_insert')").all();assert.equal(guards.length,2);
 // Explicit synthetic storage fault, then restore exact owned DDL. A cold
 // admission avoids confusing a catalog cache refusal with the semantic check.
 store.db.exec('BEGIN');try{for(const row of guards)store.db.exec('DROP TRIGGER '+row.name);store.db.prepare("INSERT INTO current_room_records(room_id,domain,record_key,revision,payload_bytes,payload_sha256,payload) SELECT room_id,domain,'z-unproven-record',revision,payload_bytes,payload_sha256,payload FROM current_room_records WHERE room_id='commons' AND domain='metadata' AND record_key='room'").run();for(const row of guards)store.db.exec(row.sql);store.db.exec('COMMIT');}catch(error){store.db.exec('ROLLBACK');throw error;}store.close();store=new RoomStore(f.filename);let refused=false;while(n<100){const before=restoreProgress(store.db),next=await post(store,request(response.body,'orphan_audit_'+n++),{json:true});if(next.status===422){assert.match(JSON.stringify(next.body),/payload lacks independent membership proof/);assert.deepEqual(restoreProgress(store.db),before);refused=true;break;}assert.equal(next.status,202,JSON.stringify(next.body));assert.equal(next.body.verified,false);response=next;}assert.equal(refused,true);assert.throws(()=>store.headSequence('commons'),error=>error.status===503);
});


