test('independent strict event history refuses an inconsistent read before full audit and retries original source safely',async t=>{
 const f=setup(t,300),store=new RoomStore(f.filename);t.after(()=>store.close());let response=await post(store,f.text),n=0;while(response.body.auditProgress?.stage!=='history_events'){response=await post(store,request(response.body,'strict_history_prepare_'+n++),{json:true});assert.equal(response.status,202,JSON.stringify(response.body));assert.ok(n<100);}const before=restoreProgress(store.db),input=request(response.body,'strict_history_fault'),prepare=store.db.prepare.bind(store.db);let injected=false;store.db.prepare=sql=>{const statement=prepare(sql);if(sql!=='SELECT sequence,id,body FROM events WHERE rowid=?')return statement;return new Proxy(statement,{get(target,key){const fn=Reflect.get(target,key,target);if(key!=='get')return typeof fn==='function'?fn.bind(target):fn;return(...args)=>{const row=fn.apply(target,args);if(!row)return row;injected=true;return{...row,body:JSON.stringify({...JSON.parse(row.body),id:'wrong-history-attribution'})};};}});};const denied=await post(store,input,{json:true});assert.equal(denied.status,422);assert.match(JSON.stringify(denied.body),/Recovery data requires operator reconciliation/);assert.equal(injected,true);store.db.prepare=prepare;assert.deepEqual(restoreProgress(store.db),before);assert.throws(()=>store.headSequence('commons'),error=>error.status===503);const retry=await post(store,input,{json:true});assert.equal(retry.status,202,JSON.stringify(retry.body));assert.ok(restoreProgress(store.db).progress.audit.strictEvents>before.progress.audit.strictEvents);assert.equal(retry.body.verified,false);
});

